/*!
 * wega-music-lap5.js - Lap 5 (The Final Lap) add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers a "lap5" track with
 * WegaMusic so WegaMusic.init() decodes it with the others and WegaMusic.play("lap5") works.
 * Track: I made it better - supplied by the player.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-lap5] load wega-music.js first"); return; }
  D.lap5 = {
    title: "I Made It Better (Final Lap Theme)",
    credit: "I made it better",
    duration: 178.05,
    loopStart: 0.42,
    loopEnd: 173.95,
    gain: 0.9,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("lap5") < 0) W.tracks.push("lap5");
})(typeof window !== "undefined" ? window : globalThis);
